# =========================================================================
# PostgreSQL Cloud Database Engine (Neon.tech / Render / Supabase)
# =========================================================================
def get_db_connection():
    db_url = os.environ.get("DATABASE_URL", "").strip()
    if not db_url:
        return None
    if db_url.startswith("postgres://"):
        db_url = db_url.replace("postgres://", "postgresql://", 1)

    try:
        import psycopg2
        return psycopg2.connect(db_url)
    except Exception as e1:
        print("[Database] PostgreSQL connection failed:", e1)
        if "channel_binding" in db_url:
            try:
                import re, psycopg2
                clean_url = re.sub(r'[?&]channel_binding=[^&]+', '', db_url)
                if '?' not in clean_url and '&' in clean_url:
                    clean_url = clean_url.replace('&', '?', 1)
                return psycopg2.connect(clean_url)
            except Exception as e2:
                print("[Database] Retry without channel_binding failed:", e2)
        return None

def init_db():
    conn = get_db_connection()
    if not conn:
        print("[Database] DATABASE_URL not available or failed to connect. Falling back to portfolio_data.json.")
        return False

    try:
        with conn.cursor() as cur:
            # 1. State Table for Portfolio JSON (Projects, Skills, Certs, Edu, Resume)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS portfolio_state (
                    id VARCHAR(50) PRIMARY KEY,
                    data JSONB NOT NULL,
                    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
                );
            """)

            # 2. Check if 'main' state is already initialized
            cur.execute("SELECT id FROM portfolio_state WHERE id = 'main';")
            row = cur.fetchone()
            if not row:
                print("[Database] Initializing PostgreSQL with existing portfolio_data.json...")
                initial_data = {}
                if os.path.exists(DATA_FILE):
                    try:
                        with open(DATA_FILE, "r", encoding="utf-8") as f:
                            initial_data = json.load(f)
                    except Exception as err:
                        print("Error reading initial data file:", err)

                import psycopg2.extras
                cur.execute(
                    "INSERT INTO portfolio_state (id, data, updated_at) VALUES ('main', %s, CURRENT_TIMESTAMP);",
                    (psycopg2.extras.Json(initial_data),)
                )
                conn.commit()
                print("[Database] Successfully migrated portfolio_data.json to PostgreSQL!")
            else:
                print("[Database] PostgreSQL portfolio_state table verified (already seeded).")
        conn.close()
        return True
    except Exception as e:
        print("[Database] Error during init_db:", e)
        if conn:
            conn.rollback()
            conn.close()
        return False

# Trigger initialization on module import
try:
    init_db()
except Exception as _e:
    print("[Database] Auto-init exception:", _e)

# =========================================================================
# Data Helpers (Hybrid Database with Seamless JSON Fallback)
# =========================================================================
def load_data():
    conn = get_db_connection()
    if conn:
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT data FROM portfolio_state WHERE id = 'main';")
                row = cur.fetchone()
                if row and row[0]:
                    conn.close()
                    data = row[0] if isinstance(row[0], dict) else json.loads(row[0])
                    # Auto-clean legacy default links and sync accurate drive links
                    needs_save = False
                    # Ensure resume driveUrl is populated
                    resume_drive = "https://drive.google.com/file/d/1vtCEfBZiPKz9CQ8ARMHXGsyeW9zrHi7P/view?usp=drive_link"
                    if not data.get("resume", {}).get("driveUrl"):
                        if "resume" not in data: data["resume"] = {}
                        data["resume"]["driveUrl"] = resume_drive
                        needs_save = True

                    # Accurate certificate drive links
                    cert_drive_map = {
                        "cert-1": "https://drive.google.com/file/d/1cl2VigQ5hxvn8Rvf95aB_rDKcxp-DC7W/view?usp=drive_link",
                        "cert-2": "https://drive.google.com/file/d/1_8l84tbuG8lmW_nmikiv928YXy97ercc/view?usp=drive_link",
                        "cert-7": "https://drive.google.com/file/d/1PQYTXUosc0CQCNKmF9qnaavIedDubfzz/view?usp=drive_link",
                        "cert-8": "https://drive.google.com/file/d/1BpAuz2XJxlBwAC32AYEE06Y6eAdSgT-x/view?usp=drive_link",
                        "cert-9": "https://drive.google.com/file/d/1LoNw328xcCGA0xyt9pPcDW8ZatINjU4V/view?usp=drive_link"
                    }
                    for c in data.get("certificates", []):
                        cid = c.get("id")
                        if cid in cert_drive_map and c.get("credentialUrl") != cert_drive_map[cid]:
                            c["credentialUrl"] = cert_drive_map[cid]
                            c["link"] = cert_drive_map[cid]
                            needs_save = True
                        elif cid not in cert_drive_map and "1vtCEfBZiPKz9CQ8ARMHXGsyeW9zrHi7P" in (c.get("credentialUrl") or ""):
                            c["credentialUrl"] = ""
                            c["link"] = ""
                            needs_save = True

                    data["moreCertificatesDriveUrl"] = "https://drive.google.com/drive/folders/1rhWWTwEuRvtgEDp8v48kL5W7qvmzBDaY?usp=drive_link"
                    data["certificatesDriveFolder"] = "https://drive.google.com/drive/folders/1rhWWTwEuRvtgEDp8v48kL5W7qvmzBDaY?usp=drive_link"

                    for e in data.get("education", []):
                        if "github.com/thesubhankar" in (e.get("link") or ""):
                            e["link"] = ""
                            needs_save = True
                        if "viewLink" not in e:
                            e["viewLink"] = e.get("link") or ""
                            needs_save = True
                        if "downloadLink" not in e:
                            e["downloadLink"] = ""
                            needs_save = True
                    if needs_save:
                        save_data(data)
                    return data
            conn.close()
        except Exception as e:
            print("[Database] Error loading from PostgreSQL, falling back to local file:", e)
            if conn:
                conn.close()

    # File-based fallback
    if not os.path.exists(DATA_FILE):
        return {"projects": [], "certificates": [], "resume": {}, "skills": []}
    try:
        with open(DATA_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception as e:
        print("Error reading data:", e)
        return {"projects": [], "certificates": [], "resume": {}, "skills": []}

def save_data(data):
    # 1. Always save locally to file as fallback backup
    try:
        with open(DATA_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
    except Exception as e:
        print("Error saving local file backup:", e)

    # 2. Save directly to PostgreSQL if DATABASE_URL is active
    conn = get_db_connection()
    if conn:
        try:
            import psycopg2.extras
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO portfolio_state (id, data, updated_at)
                    VALUES ('main', %s, CURRENT_TIMESTAMP)
                    ON CONFLICT (id) DO UPDATE SET
                        data = EXCLUDED.data,
                        updated_at = CURRENT_TIMESTAMP;
                """, (psycopg2.extras.Json(data),))
                conn.commit()
            conn.close()
        except Exception as e:
            print("[Database] Error saving to PostgreSQL:", e)
            if conn:
                conn.rollback()
                conn.close()

def delete_upload_file(rel_path):
    """Safely delete an uploaded file from disk if it resides within assets/uploads/"""
    if not rel_path or not isinstance(rel_path, str):
        return
    norm_path = rel_path.replace("\\", "/").strip()
    if norm_path.startswith("assets/uploads/"):
        abs_path = os.path.join(BASE_DIR, norm_path.replace("/", os.sep))
        if os.path.exists(abs_path) and os.path.isfile(abs_path):
            try:
                os.remove(abs_path)
                print(f"[Cleanup] Deleted file from disk: {rel_path}")
            except Exception as e:
                print(f"Error removing upload file {rel_path}:", e)

