@app.route("/api/db-status", methods=["GET"])
def db_status():
    db_url = os.environ.get("DATABASE_URL", "").strip()
    if not db_url:
        return jsonify({
            "database": "Local File (portfolio_data.json)",
            "connected": False,
            "message": "DATABASE_URL environment variable is not configured."
        })

    conn = get_db_connection()
    if not conn:
        return jsonify({
            "database": "PostgreSQL",
            "connected": False,
            "error": "Failed to connect to PostgreSQL with DATABASE_URL."
        }), 500

    try:
        with conn.cursor() as cur:
            cur.execute("SELECT version();")
            ver = cur.fetchone()[0]
            cur.execute("SELECT updated_at FROM portfolio_state WHERE id = 'main';")
            row = cur.fetchone()
            last_synced = str(row[0]) if row else None
        conn.close()

        env_user_check = get_clean_env(["ADMIN_USER", "ADMIN_USERNAME", "admin_user", "admin_username"])
        env_pass_check = get_clean_env(["ADMIN_PASS", "ADMIN_PASSWORD", "admin_pass", "admin_password"])
        return jsonify({
            "database": "PostgreSQL (Neon Cloud)",
            "connected": True,
            "status": "Healthy & Online",
            "engine": ver.split()[0] + " " + ver.split()[1],
            "last_synced": last_synced,
            "admin_user_configured": bool(env_user_check),
            "admin_pass_configured": bool(env_pass_check),
            "active_admin_username": env_user_check if env_user_check else "default (admin, subhankar, thesubhankar)"
        })
    except Exception as e:
        if conn:
            conn.close()
        return jsonify({
            "database": "PostgreSQL",
            "connected": False,
            "error": str(e)
        }), 500

