@app.route("/api/admin/skills", methods=["POST"])
def add_skill():
    data = load_data()
    req = request.get_json() or {}
    category_name = req.get("category", "").strip()
    skill_name = req.get("name", "").strip()

    if not category_name or not skill_name:
        return jsonify({"error": "Category and Skill Name are required"}), 400

    key = match_skill_key(skill_name)
    skill_item = {
        "name": skill_name,
        "key": key,
        "svg": get_skill_svg(skill_name, key)
    }

    # Find category
    cats = data.setdefault("skills", [])
    target_cat = next((c for c in cats if c.get("category", "").lower() == category_name.lower()), None)
    
    if not target_cat:
        # Create new category if not existing
        target_cat = {
            "category": category_name,
            "badge": "85%",
            "skills": []
        }
        cats.append(target_cat)

    # Check if skill already exists in that category
    if not any(s.get("name", "").lower() == skill_name.lower() for s in target_cat.get("skills", [])):
        # Insert at index 0 so new skill appears first while keeping all existing skills preserved
        target_cat.setdefault("skills", []).insert(0, skill_item)
        save_data(data)
        
    return jsonify({
        "success": True,
        "message": f"Skill '{skill_name}' added to {category_name}",
        "svg": get_skill_svg(skill_name),
        "skill": skill_item
    })

