@app.route("/api/admin/skill-category", methods=["POST"])
def update_skill_category():
    data = load_data()
    req = request.get_json() or {}
    old_cat = req.get("oldCategory", "").strip()
    new_cat = req.get("newCategory", "").strip()
    badge = req.get("badge", "").strip()

    if not old_cat and not new_cat:
        return jsonify({"error": "Category name is required"}), 400

    cats = data.setdefault("skills", [])
    found = next((c for c in cats if c.get("category", "").lower() == old_cat.lower()), None)
    
    if found:
        if new_cat:
            found["category"] = new_cat
        if badge:
            found["badge"] = badge
    else:
        found = {
            "category": new_cat or old_cat,
            "badge": badge or "85%",
            "skills": []
        }
        cats.append(found)

    # Process skills if provided in payload
    if "skills" in req:
        raw_skills = req.get("skills")
        parsed_names = []
        if isinstance(raw_skills, str):
            parsed_names = [s.strip() for s in raw_skills.split(",") if s.strip()]
        elif isinstance(raw_skills, list):
            for item in raw_skills:
                if isinstance(item, dict):
                    name = item.get("name", "").strip()
                elif isinstance(item, str):
                    name = item.strip()
                else:
                    name = ""
                if name:
                    parsed_names.append(name)

        existing_skills_map = {
            s.get("name", "").lower(): s
            for s in found.get("skills", [])
            if isinstance(s, dict) and s.get("name")
        }

        updated_skills = []
        for name in parsed_names:
            lower = name.lower()
            if lower in existing_skills_map and existing_skills_map[lower].get("svg"):
                sk = existing_skills_map[lower].copy()
                sk["name"] = name
                if not sk.get("key"):
                    sk["key"] = match_skill_key(name)
                updated_skills.append(sk)
            else:
                key = match_skill_key(name)
                updated_skills.append({
                    "name": name,
                    "key": key,
                    "svg": get_skill_svg(name, key)
                })

        found["skills"] = updated_skills

    save_data(data)
    return jsonify({"success": True, "message": "Skill category updated successfully", "category": found})

