@app.route("/api/admin/education", methods=["POST"])
def add_or_update_education():
    data = load_data()
    
    # Support both form data and json
    if request.is_json:
        req = request.get_json() or {}
    else:
        req = request.form.to_dict()

    degree = req.get("degree", "").strip()
    institution = req.get("institution", "").strip()
    if not degree or not institution:
        return jsonify({"error": "Degree and Institution are required"}), 400

    edu_id = req.get("id") or ("edu_" + str(int(time.time())))
    timeline = req.get("timeline", "").strip()
    status = req.get("status", "Completed").strip()
    grade = req.get("grade", "").strip()
    details = req.get("details", "").strip()
    view_link = req.get("viewLink", req.get("link", "")).strip()
    if "github.com/thesubhankar" in view_link and not req.get("viewLink"):
        view_link = ""
    download_link = req.get("downloadLink", "").strip()
    color = req.get("color", "cyan").strip()

    new_edu = {
        "id": edu_id,
        "degree": degree,
        "institution": institution,
        "timeline": timeline,
        "status": status,
        "grade": grade,
        "details": details,
        "viewLink": view_link,
        "downloadLink": download_link,
        "link": view_link or download_link,
        "color": color
    }

    edu_list = data.setdefault("education", [])
    existing_idx = next((i for i, e in enumerate(edu_list) if e.get("id") == edu_id), -1)

    if existing_idx >= 0:
        edu_list[existing_idx] = new_edu
    else:
        edu_list.append(new_edu)

    save_data(data)
    return jsonify({"success": True, "message": "Education milestone saved successfully", "education": new_edu})

@app.route("/api/admin/education/<edu_id>", methods=["DELETE"])
def delete_education(edu_id):
    data = load_data()
    data["education"] = [e for e in data.get("education", []) if e.get("id") != edu_id]
    save_data(data)
    return jsonify({"success": True, "message": "Education milestone deleted"})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=True)
